"""The settings quartet for the cinbase keys added by this family.

A cinbase setting lives in four places or it is silently half-dead: the
``CinBaseConfig.__init__`` default, the shipped default in **all eight**
``python/input_methods/<ime>/config/config.json``, a control in the shared
settings page (``python/cinbase/config/config.htm``, scripted by
``js/config.js``), and the read site in the engine. These checks keep the four
in step for the keys added by tickets 12/13/14/17.
"""

import json
import os
import re
import sys
import tempfile
import unittest
from unittest import mock

ROOT = os.path.abspath(os.path.join(os.path.dirname(__file__), os.path.pardir))
for _path in (os.path.join(ROOT, "python"), os.path.dirname(os.path.abspath(__file__))):
    if _path not in sys.path:
        sys.path.insert(0, _path)

from test_cinbase_shift_to_english import CinbaseKeyHarness  # noqa: E402

CINBASE_DIR = os.path.join(ROOT, "python", "cinbase")
CONFIG_DIR = os.path.join(ROOT, "python", "input_methods")

IME_DIRS = ("chearray", "checj", "chedayi", "cheez",
            "cheliu", "chephonetic", "chepinyin", "chesimplex")

# 这一家子新增的設定：鍵 -> 內定值
NEW_KEYS = {
    "candFontName": "MingLiu",   # issue #582
    "selKeyType": 0,             # issue #463/#539
    "leadInKey": "`",             # issue #525
    "enableCtrlSymbols": True,    # issue #826
}


def fresh_config():
    from cinbase.config import CinBaseConfigClass
    return CinBaseConfigClass()


class CinbaseConfigQuartetTests(unittest.TestCase):

    def shipped(self, ime):
        path = os.path.join(CONFIG_DIR, ime, "config", "config.json")
        with open(path, encoding="utf-8") as handle:
            return json.load(handle)

    def test_every_new_key_has_an_init_default(self):
        cfg = fresh_config()
        for key, value in NEW_KEYS.items():
            self.assertTrue(hasattr(cfg, key), "%s has no __init__ default" % key)
            self.assertEqual(getattr(cfg, key), value, "%s default" % key)

    def test_every_shipped_default_ships_the_new_keys(self):
        self.assertEqual(8, len(IME_DIRS))
        for ime in IME_DIRS:
            data = self.shipped(ime)
            for key, value in NEW_KEYS.items():
                self.assertIn(key, data, "%s is missing from %s" % (key, ime))
                self.assertEqual(value, data[key],
                                 "%s in %s must be the documented default" % (key, ime))

    def test_the_settings_page_carries_a_control_for_each_key(self):
        with open(os.path.join(CINBASE_DIR, "config", "config.htm"),
                  encoding="utf-8") as handle:
            page = handle.read()
        with open(os.path.join(CINBASE_DIR, "config", "js", "config.js"),
                  encoding="utf-8") as handle:
            script = handle.read()
        for key in NEW_KEYS:
            self.assertRegex(page, r'id="%s"' % key,
                             "no control for %s on the settings page" % key)
            self.assertRegex(page, r'name="%s"' % key,
                             "the control for %s is unnamed" % key)
        # 選字鍵順序是 select，選項由 js 建立
        self.assertIn("selKeyType", script)

    def test_the_settings_script_agrees_with_the_python_defaults(self):
        # config.js carries its own copy of two of these decisions: the 選字鍵
        # 順序 option rows and the index used when a shipped config.json has no
        # selKeyType. The engine reads the Python side, so the copies must be
        # identical or a saved index selects the wrong row.
        with open(os.path.join(CINBASE_DIR, "config", "js", "config.js"),
                  encoding="utf-8") as handle:
            script = handle.read()
        from cinbase.config import CinBaseConfigClass, selKeys

        rows = re.findall(r'"([^"]+)"',
                          re.search(r"var selSelKeys = \[(.*?)\];",
                                    script, re.S).group(1))
        self.assertEqual(list(selKeys), rows,
                         "the select options drift from config.py selKeys")
        fallback = re.search(
            r'checjConfig\.selKeyType === "undefined"\) \? (\d+) :',
            script).group(1)
        self.assertEqual(CinBaseConfigClass().selKeyType, int(fallback),
                         "the js index fallback is not the python default")

    def test_invalid_values_fall_back(self):
        cfg = fresh_config()

        cfg.candFontName = ""
        cfg.sanitize()
        self.assertEqual("MingLiu", cfg.candFontName)
        cfg.candFontName = None
        cfg.sanitize()
        self.assertEqual("MingLiu", cfg.candFontName)
        cfg.candFontName = "  Noto Sans TC  "
        cfg.sanitize()
        self.assertEqual("Noto Sans TC", cfg.candFontName)

        cfg.leadInKey = ""
        cfg.sanitize()
        self.assertEqual("`", cfg.leadInKey)
        cfg.leadInKey = 3
        cfg.sanitize()
        self.assertEqual("3", cfg.leadInKey)

        cfg.selKeyType = 99
        cfg.sanitize()
        self.assertEqual(0, cfg.selKeyType)
        cfg.selKeyType = "x"
        cfg.sanitize()
        self.assertEqual(0, cfg.selKeyType)

        cfg.enableCtrlSymbols = "yes"
        cfg.sanitize()
        self.assertIs(True, cfg.enableCtrlSymbols)

    def test_sel_key_rows(self):
        cfg = fresh_config()
        self.assertEqual("1234567890", cfg.getSelKeys())
        cfg.selKeyType = 1
        self.assertEqual("0123456789", cfg.getSelKeys())


class CinbaseConfigReadSiteTests(CinbaseKeyHarness):

    def test_the_engine_reads_each_value(self):
        service = self.activate_chesimplex()

        self.assertEqual("MingLiu",
                         service.currentReply["customizeUI"]["candFontName"])
        self.assertEqual(service.cfg.getSelKeys(), service.selKeys)
        self.assertEqual("`", service.leadInKey)
        self.assertIs(True, service.enableCtrlSymbols)

    def test_a_configured_font_name_reaches_the_candidate_window(self):
        service = self.activate_chesimplex()
        service.cfg.candFontName = "Noto Sans TC"
        service.currentReply = {}

        service.cinbase.applyConfig(service)

        self.assertEqual("Noto Sans TC",
                         service.currentReply["customizeUI"]["candFontName"])


class ChewingConfigReadSiteTests(unittest.TestCase):
    # #582 names both candidate-drawing paths: the cinbase window above and the
    # chewing window, whose applyConfig() used to pass the literal 'MingLiu'.

    def test_the_chewing_config_ships_the_font_default(self):
        from input_methods.chewing import chewing_config

        with tempfile.TemporaryDirectory() as temp_dir:
            with mock.patch.dict(os.environ, {"APPDATA": temp_dir}):
                cfg = chewing_config.ChewingConfig()
                self.assertEqual(chewing_config.DEF_FONT_NAME, cfg.candFontName)
                # a saved empty value falls back instead of reaching the UI
                with open(cfg.getConfigFile(), "w", encoding="utf-8") as handle:
                    json.dump({"candFontName": ""}, handle)
                cfg.candFontName = "stale"
                cfg.load()
                self.assertEqual(chewing_config.DEF_FONT_NAME, cfg.candFontName)

    def test_the_configured_font_reaches_the_chewing_window(self):
        from input_methods.chewing import chewing_config, chewing_ime

        context = mock.MagicMock()
        service = chewing_ime.ChewingTextService.__new__(
            chewing_ime.ChewingTextService)
        service.configVersion = None
        service.chewingContext = context
        service.currentReply = {}
        service.opencc = None
        service.hasLangButtons = False
        service.updateSwitchLangIcon = False
        service.langMode = context.get_ChiEngMode.return_value
        service.shapeMode = context.get_ShapeMode.return_value
        service.icon_dir = "icons"
        service.client = mock.MagicMock(isWindows8Above=False)

        cfg = chewing_config.chewingConfig
        previous = cfg.candFontName
        cfg.candFontName = "Noto Sans TC"
        try:
            chewing_ime.ChewingTextService.applyConfig(service)
        finally:
            cfg.candFontName = previous

        self.assertEqual("Noto Sans TC",
                         service.currentReply["customizeUI"]["candFontName"])


if __name__ == "__main__":
    unittest.main()
